const cmds = [
  ["protection", "\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json"],
  ["conversation", "\"$HORIZON_BIN\" inbox list --mine --unread --kind conversation --json"],
  ["env", "printf '%s\\n' \"$HORIZON_BIN\" \"$ARCHON_HORIZON_ROOT\""]
];
const out = await Promise.all(cmds.map(async ([name,cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000});
  return `## ${name}\n${r.output}`;
}));
text(out.join("\n"));

const ids=["I-0074","I-1222","I-1482","I-0492","I-0838"];
const out=await Promise.all(ids.map(async id=>{
 const r=await tools.exec_command({cmd:`"$HORIZON_BIN" inbox show ${id} --json | jq '{id,body,comments}'`,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:12000});
 return `## ${id}\n${r.output}`;
}));
text(out.join("\n"));

const ids=["I-0074","I-0492","I-0838"];
for (const id of ids) {
  const r=await tools.exec_command({cmd:`"$HORIZON_BIN" inbox show ${id} --json 2>/dev/null | jq -r '.body, (.comments[]?.body)'`,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:30000,max_output_tokens:12000});
  text(`## ${id}\n${r.output}`);
}

const cmds=[
 ["defs","rg -n \"(rightRestrictionFinalBaseChangeEquiv_naturality|pic0FiniteStageFinalBaseChangeEquiv_naturality|scalarExtensionMapOfAlgHom_comp|pic0FiniteStageRestrictionRight|overlapFinalBaseChangeEquiv|resHom_resHom)\" AlgebraicJacobian"],
 ["files","rg --files AlgebraicJacobian/Picard | rg 'Pic0FiniteStage|FinalBaseChange|Restriction'"],
 ["status","git status --short -- AlgebraicJacobian/Picard"]
];
const out=await Promise.all(cmds.map(async ([n,c])=>{const r=await tools.exec_command({cmd:c,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:20000});return `## ${n}\n${r.output}`;})); text(out.join("\n"));

const files=[
"AlgebraicJacobian/Picard/Pic0FiniteStageFinalBaseChange.lean",
"AlgebraicJacobian/Picard/Pic0FiniteStageRestrictionNaturality.lean",
"AlgebraicJacobian/Picard/Pic0FiniteStageOverlapRings.lean",
"AlgebraicJacobian/Picard/Pic0FiniteStageTransitionModels.lean",
"AlgebraicJacobian/Descent/TensorProductFieldTowerMap.lean"
];
const out=await Promise.all(files.map(async f=>{const r=await tools.exec_command({cmd:`nl -ba ${f} | sed -n '1,230p'`,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:15000});return `## ${f}\n${r.output}`})); text(out.join("\n"));

const tool=tools.mcp__lean_lsp__lean_diagnostic_messages;
const paths=[
"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0FiniteStageRestrictionNaturality.lean",
"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0FiniteStageFinalBaseChange.lean"
];
const rs=await Promise.all(paths.map(file_path=>tool({file_path,timeout_s:120})));
rs.forEach((r,i)=>{text(paths[i]);text(r)});

